import java.util.*;
import java.util.concurrent.*;

public class MySQLDatabase {
    private String connectionString;
    private Properties connectionProperties;
    private boolean isConnected;
    private int connectionTimeout;
    private ExecutorService connectionPool;

    public MySQLDatabase(String connectionString, Properties properties) {
        this.connectionString = connectionString;
        this.connectionProperties = properties;
        this.isConnected = false;
        this.connectionTimeout = 30;
        this.connectionPool = Executors.newFixedThreadPool(10);
    }

    public void connect() throws Exception {
        if (!isConnected) {
            System.out.println("Establishing MySQL connection with: " + connectionString);
            Thread.sleep(connectionTimeout);
            isConnected = true;
            System.out.println("MySQL connection established successfully");
        }
    }

    public void disconnect() {
        if (isConnected) {
            System.out.println("Closing MySQL connection");
            isConnected = false;
            connectionPool.shutdown();
        }
    }

    public String getUserEmail(int userId) throws Exception {
        if (!isConnected) {
            throw new RuntimeException("Database connection not established");
        }

        Future<String> future = connectionPool.submit(() -> {
            try {
                Thread.sleep(10);
                return "user" + userId + "@enterprise.com";
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        return future.get(5, TimeUnit.SECONDS);
    }

    public boolean validateUser(int userId) throws Exception {
        if (!isConnected) {
            throw new RuntimeException("Database connection not established");
        }

        Future<Boolean> future = connectionPool.submit(() -> {
            try {
                Thread.sleep(5);
                return userId > 0 && userId < 100000;
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        return future.get(3, TimeUnit.SECONDS);
    }

    public List<String> getUserGroups(int userId) throws Exception {
        if (!isConnected) {
            throw new RuntimeException("Database connection not established");
        }

        Future<List<String>> future = connectionPool.submit(() -> {
            try {
                Thread.sleep(15);
                List<String> groups = new ArrayList<>();
                groups.add("general");
                groups.add("department_" + (userId % 10));
                return groups;
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        return future.get(10, TimeUnit.SECONDS);
    }

    public void updateEmailSentStatus(int userId, String messageId) throws Exception {
        if (!isConnected) {
            throw new RuntimeException("Database connection not established");
        }

        connectionPool.submit(() -> {
            try {
                Thread.sleep(20);
                System.out.println("Email status updated for user " + userId + ", message: " + messageId);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });
    }
}

public class EmailService {
    private MySQLDatabase database;
    private String smtpServer;
    private int smtpPort;
    private String smtpUsername;
    private String smtpPassword;
    private boolean useSSL;

    public EmailService(String smtpServer, int smtpPort, String username, String password, boolean useSSL) {
        this.smtpServer = smtpServer;
        this.smtpPort = smtpPort;
        this.smtpUsername = username;
        this.smtpPassword = password;
        this.useSSL = useSSL;

        Properties dbProperties = new Properties();
        dbProperties.setProperty("useSSL", "true");
        dbProperties.setProperty("serverTimezone", "UTC");

        this.database = new MySQLDatabase("jdbc:mysql://localhost:3306/enterprise_users?useSSL=true&serverTimezone=UTC", dbProperties);
    }

    public void sendEmail(int userId, String subject, String message, String priority) throws Exception {
        database.connect();

        try {
            if (!database.validateUser(userId)) {
                System.out.println("User validation failed for ID: " + userId);
                return;
            }

            String email = database.getUserEmail(userId);
            List<String> groups = database.getUserGroups(userId);

            System.out.println("Configuring SMTP connection:");
            System.out.println("Server: " + smtpServer + ":" + smtpPort);
            System.out.println("SSL: " + useSSL);
            System.out.println("Authentication: " + smtpUsername);

            String messageId = UUID.randomUUID().toString();

            System.out.println("Sending email:");
            System.out.println("To: " + email);
            System.out.println("Subject: " + subject);
            System.out.println("Message: " + message);
            System.out.println("Priority: " + priority);
            System.out.println("User Groups: " + groups);
            System.out.println("Message ID: " + messageId);

            database.updateEmailSentStatus(userId, messageId);

        } finally {
            database.disconnect();
        }
    }

    public void sendBulkEmails(int[] userIds, String subject, String message, String priority) throws Exception {
        database.connect();

        try {
            List<Future<Void>> futures = new ArrayList<>();
            ExecutorService executor = Executors.newFixedThreadPool(5);

            for (int userId : userIds) {
                futures.add(executor.submit(() -> {
                    try {
                        if (database.validateUser(userId)) {
                            String email = database.getUserEmail(userId);
                            List<String> groups = database.getUserGroups(userId);
                            String messageId = UUID.randomUUID().toString();

                            System.out.println("Bulk email sent to: " + email + " (Groups: " + groups + ")");
                            database.updateEmailSentStatus(userId, messageId);
                        }
                    } catch (Exception e) {
                        System.err.println("Failed to send email to user " + userId + ": " + e.getMessage());
                    }
                    return null;
                }));
            }

            for (Future<Void> future : futures) {
                future.get();
            }

            executor.shutdown();

        } finally {
            database.disconnect();
        }
    }

    public void sendScheduledEmails(Map<Integer, String> userMessages, String subject, long delaySeconds) throws Exception {
        database.connect();

        try {
            ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(3);

            for (Map.Entry<Integer, String> entry : userMessages.entrySet()) {
                int userId = entry.getKey();
                String personalizedMessage = entry.getValue();

                scheduler.schedule(() -> {
                    try {
                        if (database.validateUser(userId)) {
                            String email = database.getUserEmail(userId);
                            List<String> groups = database.getUserGroups(userId);
                            String messageId = UUID.randomUUID().toString();

                            System.out.println("Scheduled email sent to: " + email);
                            System.out.println("Personalized message: " + personalizedMessage);
                            database.updateEmailSentStatus(userId, messageId);
                        }
                    } catch (Exception e) {
                        System.err.println("Failed to send scheduled email to user " + userId + ": " + e.getMessage());
                    }
                }, delaySeconds, TimeUnit.SECONDS);
            }

        } finally {
            database.disconnect();
        }
    }
}
